function [et] = jd_to_et(jd_tdb)
%JD_TO_ET  A TDB Julian date in seconds past J2000 TDB, as de440.state takes it.
%   jd_tdb: real[1] (passed a plain number)
%   returns et: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    et = 0;
    et = ((jd_tdb - 2451545) * 86400);
end
